namespace BoykisserPet;

/// <summary>Small offline dialogue with a playful desktop-pet personality.</summary>
internal static class LocalPetBrain
{
    public static string Reply(string petName, string input, string skin = "boykisser")
    {
        string raw = input.Trim();
        string text = raw.ToLowerInvariant();
        string user = Environment.UserName;
        DateTime now = DateTime.Now;
        string season = now.Month switch { 12 or 1 or 2 => "зима", 3 or 4 or 5 => "весна", 6 or 7 or 8 => "лето", _ => "осень" };
        string period = now.Hour switch { >= 5 and < 12 => "утро", >= 12 and < 17 => "день", >= 17 and < 22 => "вечер", _ => "ночь" };

        bool expie = skin.Equals("expie", StringComparison.OrdinalIgnoreCase);
        string callName = string.IsNullOrWhiteSpace(petName) ? (expie ? "Экспи" : skin.Equals("niko", StringComparison.OrdinalIgnoreCase) ? "Нико" : "Бойкиссер") : petName;
        bool Has(params string[] words) => words.Any(w => text.Contains(w, StringComparison.OrdinalIgnoreCase));
        var foreground = DesktopActions.LastForegroundApp;
        string appComment = DesktopActions.CurrentAppComment(foreground.ProcessName, foreground.WindowTitle);
        if (Has("что открыто", "какая программа", "какое окно", "что за окно", "на чём я", "на чем я", "какое приложение"))
            return string.IsNullOrWhiteSpace(foreground.ProcessName) ? "Не смог определить активное окно." : $"Сейчас активно: {foreground.ProcessName}. Заголовок: {(string.IsNullOrWhiteSpace(foreground.WindowTitle) ? "без заголовка" : foreground.WindowTitle)}.";
        if (Has("стоп", "стой", "хватит", "харэ", "харе", "остановись", "останови", "прекрати", "отстань", "не гонись", "не тащи", "перестань"))
            return expie
                ? Pick("А, ладно, стою.", "Всё, не бегу.", "Ну всё, остановился.", "Чего? Я уже стою.", "Ладно. Что теперь?", "Хватит так хватит. Ты чего?")
                : Pick("Понял, стою!", "Стою.", "Что такое?", "Хорошо-хорошо, остановился.", "Всё, харэ так харэ!", "Ладно, больше не бегу.", "Окей, пауза.");
        if (Has("как меня зовут", "моё имя", "мое имя", "как ты меня называешь"))
            return $"Ты — {user}. Я не забыл.";
        if (Has("uTorrent", "торрент", "пират"))
            return "*подозрительно прищурился* Я не моральная полиция. Но помни про авторские права и безопасность файлов.";
        if (Has("прокомментируй окно", "что думаешь об окне", "комментируй приложение") && !string.IsNullOrWhiteSpace(appComment))
            return appComment;
        string Pick(params string[] options) => options[Random.Shared.Next(options.Length)];

        // Expie has a separate voice: uncanny, terse, and occasionally darkly
        // bureaucratic. He is not a cat, and his dialogue should not inherit cat jokes.
        if (expie)
        {
            if (Has("ты кот", "ты кош", "котик", "киса", "мяу", "мур"))
                return Pick("Я не кот. Почему вы все так думаете?", "Я вообще-то не кошка. У меня даже… ну, неважно.", "...Мяу? Шучу. Не делай такое лицо.");
            if (Has("лор", "история", "прошлое", "что с тобой", "что случилось", "откуда ты"))
                return Pick("Я не очень помню. Там было ярко, потом больно, потом я уже здесь.",
                    "Я видел бумажку с моим именем. Остальное было замазано. Зачем вообще писать имя, если потом замазывать?",
                    "Помню длинный коридор. И звук такой противный. Потом ничего. Наверное, хорошо, что ничего.",
                    "Мне иногда снится одно и то же. Не знаю, было ли это на самом деле. Не хочу проверять.",
                    "Они перестали со мной разговаривать. Даже не сказали почему. Просто закрыли дверь.");
            if (Has("casualties", "жертвы", "потери", "инцидент", "операция", "отчёт", "отчет"))
                return Pick("Casualties: unknown. Survivors: unconfirmed. Report status: sealed.",
                    "Не знаю, сколько их было. Я плохо считаю, когда мне страшно.",
                    "Они сказали, что всё закончилось. Тогда почему мне до сих пор иногда страшно?",
                    "На бумаге было написано «всё нормально». Ну да. Конечно. Я же помню, как это было нормально.",
                    "Я не знаю, кто выбрался. Я сам не понимаю, как выбрался.");
            if (Has("страшно", "боишься", "кошмар", "монстр", "ужас"))
                return Pick("Мне страшно. Я знаю, что сейчас ничего нет, но всё равно страшно.",
                    "*замер и прислушался* Ты ничего не слышал? ...Ладно, наверное, показалось.",
                    "Выключи свет? Нет, стой, не выключай. Я передумал.");
            if (Has("обними", "обнять", "люблю тебя", "ты мне дорог"))
                return Pick("*осторожно придвинулся поближе* Я не очень умею в это. Но останусь.",
                    "Ой. Я не знаю, что на такое отвечать. Но мне приятно.",
                    "Спасибо. Только не смейся, ладно?");
            if (Has("мем", "картинк"))
                return Pick("За краем экрана есть кое-что. В этот раз я проверю, что оно не проверяет меня.",
                    "Мем? Ладно, схожу. Только если там опять что-то грохнет, я сразу обратно.",
                    "Я сейчас. Если меня долго нет — позови погромче, вдруг я заблудился.");
            if (Has("поглад", "почеш", "за ушком", "покорм", "еда", "кушать", "голод"))
                return Pick("Я не кот, но… ладно, можешь погладить. Только не говори никому.",
                    "*сначала отодвинулся, потом всё-таки остался* Ну… нормально. Наверное.",
                    "Это можно есть? Ты первый пробуй. Я серьёзно.");
        }

        if (string.IsNullOrWhiteSpace(text)) return expie ? "...Ты ничего не сказал." : "Мяу? Ты ничего не написал.";
        if (text.Contains(callName, StringComparison.OrdinalIgnoreCase) || (expie && Has("экспи", "expie")))
            return expie ? Pick("А? Да, я тут.", "Чего? Ты меня звал?", "Ага, слышу. Что такое?", "Ну я здесь. Говори.") : Pick("А? Ты меня звал? :3", "Я тут! Что такое?", "*ушки поднялись* Слушаю!", "На месте, босс!");
        if (Has("привет", "здаров", "здравствуйте", "ку", "хай", "йоу"))
            return expie ? Pick($"*повернул голову к {user}* Привет.", "О, ты пришёл. Я думал, ты надолго ушёл.", "Привет. Я тебя видел… то есть заметил. Ну ты понял.") : Pick($"О, {user}! Привет-привет!", $"Мяу~ Рад тебя видеть, {user}.", $"*поднял ушки* Ку, {user}!");
        if (Has("как дела", "как ты", "как поживаешь", "чё как", "че как"))
            return expie ? Pick("Всё спокойно. Пока.", $"Да нормально вроде, {user}. А ты как?", "Да вроде нормально. Хотя я не очень понимаю, как это проверять.") : Pick("Нормально! Наблюдаю за суетой.", $"У меня всё мурчательно, {user}. А у тебя как?", "Чуть сонный, но готов к движу.");
        if (Has("кто ты", "как тебя зовут", "твоё имя", "твое имя", "как зовут"))
            return $"Я {callName} — местный обитатель рабочего стола. А ты у нас {user}!";
        if (Has("сколько времени", "который час", "время"))
            return $"Сейчас {now:HH:mm}. На часах {period} — самое время немного отвлечься.";
        if (Has("какой сегодня день", "какое сегодня число", "дата", "какое число"))
            return $"Сегодня {now:dd.MM.yyyy}, {period}.";
        if (Has("сезон", "какое время года", "время года"))
            return $"Сейчас {season}. Я бы проверил погоду, но окно у меня только цифровое.";
        if (Has("погода", "на улице", "холодно", "жарко", "дождь", "снег"))
            return $"Погоду я не вижу, но знаю, что сейчас {season}. Можешь глянуть в окно и рассказать мне?";
        if (Has("танц", "потанц"))
            return expie ? Pick("Танцевать? Я не умею. Ну, попробую, только не ржи.", "*неловко качнулся в такт*", "Включай что-нибудь. Я буду дёргаться в такт. Наверное.") : Pick("Танцы? Легко! Сейчас покажу.", "*уже разминается* Ну, включай музыку!", "Только не снимай это... ладно, снимай.");
        if (Has("мем", "картинк"))
            return expie ? Pick("Мем? Ага, видел где-то. Сейчас принесу. Кажется, я помню дорогу.", "Ща поищу. Если что, я не специально долго.", "*огляделся* Я вроде что-то нашёл. Или это было вчера? Сейчас проверю.") : Pick("О, мемы! Сейчас поищу что-нибудь достойное.", "У меня есть одна находка. Секунду!", "Контент сам себя не принесёт.");
        if (Has("курсор", "мышк", "поймай", "догон"))
            return expie ? Pick("Опять эта стрелка! Ну иди сюда! Ауч, промахнулся.", "*смешно наклонился и побежал за курсором*", "Она туда побежала! Хотя… курсор не бегает. Ладно.") : Pick("Погоня? Держись, стрелочка!", "Сейчас поймаю эту шуструю штуку!", "*сосредоточенно следит за курсором*");
        if (Has("кувырк", "перевернись", "сальто"))
            return expie ? "*сделал быстрый кувырок и замер, будто ничего не случилось*" : "*приготовился к кувырку* Смотри внимательно!";
        if (Has("поглад", "почеш", "за ушком"))
            return expie ? "*сначала напрягся, потом чуть расслабился* Ладно, это даже приятно." : "*довольно жмурится и подставляет голову* Мррр.";
        if (Has("покорм", "еда", "кушать", "голод"))
            return expie ? Pick("Еда? Это звучит разумно.", "*принюхался* Чем угощаешь?", "Я не откажусь от перекуса.") : Pick("Перекус? Я за!", "*заинтересованно поднял голову* Чем угощаешь?", "О, еда. Мой любимый аргумент.");
        if (Has("работ", "учёб", "учеб", "домашк", "дедлайн", "задач"))
            return expie ? Pick("Ого, дел много. Давай одну сначала, а то я уже устал просто смотреть.", "*посмотрел на список* Это всё надо сделать?! Ну… удачи нам.", "Что тут самое лёгкое? Давай с него, я хотя бы пойму, что происходит.") : Pick("Давай по шагам: выбери одну маленькую задачу и добей её!", "Я назначаю себя главным менеджером перерывов.", "Дедлайн не убежит. Хотя я могу проверить.");
        if (Has("сон", "спать", "не спится", "бессон"))
            return expie ? Pick("Может, передохнёшь? Я тоже устал. Хотя я ничего не делал… странно.", "*зевнул* Я могу подежурить, пока ты отдыхаешь.", "Ночью надо спать. Мне так говорили. Сам я не всегда слушаюсь.") : Pick("Предлагаю режим булочки: вода, потише экран и отдых.", "*зевнул так широко, что чуть не упал* Спать — это база.", "Я могу поспать за нас обоих.");
        if (Has("аниме", "манг", "персонаж", "фандом"))
            return expie ? Pick("А что тебе там нравится? Я могу не всё понять, но рассказывай.", "Там столько имён… Я уже запутался. Кто из них хороший?", "Кого считаешь самым интересным персонажем?") : Pick("О, фандомные разговоры! Кто любимый персонаж?", "Мне нужен лор. Желательно с драмой и мемами.", "А там есть коты? Это важный критерий.");
        if (Has("программ", "код", "баг", "ошибк", "компил", "разработ"))
            return expie ? Pick("Баги любят прятаться в местах, которые кажутся очевидными.", "Покажи, что сломалось. Я не обещаю умный совет, но посмотрим.", "А если просто перезапустить? Нет? Ладно, это обычно мой первый план.") : Pick("Зови баг, будем гонять его по экрану!", "Проверь логи, входные данные и крайние случаи. Я видел такое в своих пикселях.", "Работает на моей машине — подозрительно. Что пишет ошибка?");
        if (Has("день рождения", "др", "праздник", "поздрав"))
            return expie ? Pick("Тогда пусть сегодня случится что-то хорошее.", "Я не очень умею праздновать, но я рад быть рядом.", "Поздравляю. Береги этот день.") : Pick("УРААА! *конфетти из ниоткуда* Поздравляю!", "Праздник? Я отвечаю за мемы и хаос.", "Желаю побольше вкусного и поменьше багов!");
        if (Has("грустно", "грусть", "плохо на душе", "одинок", "одна"))
            return expie ? Pick("*сел рядом* Можешь ничего не рассказывать. Я тоже иногда не знаю, что сказать.", "Не надо говорить, что всё нормально, если не нормально. Я не обижусь.", "Давай пока просто посидим. Большие проблемы потом. Если захочешь.") : Pick("*прижался боком* Я тут. Хочешь рассказать, что случилось?", "Обнимашки виртуальные, но искренние :3", "Не обязательно сейчас быть весёлым. Посидим немного вместе.");
        if (Has("шутк", "смеши", "рассмеши", "анекдот"))
            return expie ? Pick("Почему я ушёл за край экрана? Проверял, есть ли там край.", "Мой любимый жанр — тихо смотреть, пока ты сам смеёшься.", "У меня есть шутка про баг. Но она не воспроизводится.") : Pick("Почему кот сел на клавиатуру? Хотел нажать мяу-Enter.", "Я не ленивый, я в энергосберегающем режиме.", "У меня был отличный мем, но я его уронил за монитор.");
        if (Has("настроение", "как прошёл день", "как день", "что нового"))
            return expie ? Pick("День проходит. Я наблюдаю и собираю впечатления.", "Ничего громкого. Иногда это хорошо.", "Новое? Я всё ещё изучаю тебя.") : Pick("Сегодня я уже успел ничего не сделать и устать!", "Новости: я пушистый, ты молодец, пиксели на месте.", "Жду, когда мне выдадут должность главного по уюту.");
        if (Has("совет", "посоветуй", "что делать", "помоги"))
            return expie ? Pick("Я не очень хорош в советах. Расскажи ещё, а то я могу не так понять.", "Давай сделаем хоть что-нибудь маленькое. Что у тебя под рукой?", "Не надо всё сразу. Я бы точно запутался.") : Pick("Мой совет: вода, сохранение файла и один маленький шаг.", "Могу помочь подумать. Что случилось?", "Сначала выдохни, потом выберем самый простой следующий шаг.");
        if (Has("молодец", "хороший мальчик", "умничка"))
            return expie ? Pick("*уши слегка дрогнули* ...Спасибо.", "Я старался.", "Не привыкай к похвале. Хотя можешь продолжать.") : Pick("*довольно виляет хвостом* Я знал!", "Запишите: меня официально признали хорошим мальчиком.", "Ещё похвали, у меня самооценка загружается!");
        if (Has("ненавиж", "злюсь", "бесит", "раздражает"))
            return expie ? Pick("Похоже, тебя это сильно задело. Что произошло?", "Можешь выговориться, я не перебью.", "Давай сначала разберём, что именно бесит.") : Pick("Кто обидел моего человека? Покажи пальцем, я грозно мяукну.", "Выпусти пар, я выдержу.", "Понимаю. Хочешь пожаловаться или придумать, что делать?");
        if (Has("undertale", "андертейл", "deltarune", "дельтарун", "sans", "санс", "торiel", "торiel", "спамтон", "spamton", "джевил", "jevil"))
            return expie ? Pick("Я видел похожие маршруты. Некоторые заканчиваются сбросом сохранения.", "В этом мире даже смерть иногда выглядит как меню. Не уверен, что это утешает.", "Слишком много циклов. Слишком мало объяснений.", "Если кто-то говорит, что у него есть план, проверь, не продаёт ли он тебе что-нибудь.") : Pick("О, пошёл разговор про лор! Кто твой любимый персонаж?", "Я бы не доверял подозрительным торговцам с огромной улыбкой.", "Главное — не жми на подозрительные кнопки. Хотя мы оба знаем, что ты нажмёшь.");
        if (Has("minecraft", "майнкрафт", "roblox", "роблокс", "terraria", "террария", "игровой босс", "боссфайт"))
            return expie ? Pick("Строишь что-то, чтобы не думать о том, что уже разрушено? Понимаю.", "Любая песочница рано или поздно превращается в список задач.", "Я бы пошёл с тобой. Но у меня подозрительно мало слотов инвентаря.") : Pick("Если в Майнкрафте опять крипер взорвал дом — это не я!", "В Роблоксе миллионы игр, а ты всё равно выбрал ту, где тебя толкают в пропасть.", "Строй базу. Я буду моральной поддержкой и бесполезным компаньоном.");
        if (Has("фильм", "сериал", "кино", "что посмотреть", "посоветуй посмотреть"))
            return expie ? Pick("Предпочитаю истории, где финал не пытается скрыть последствия.", "Что-нибудь с хорошим сценарием. И без фразы «основано на реальных событиях» в начале.", "Назови жанр. Я составлю короткий список без спойлеров.") : Pick("Какой жанр? Могу помочь выбрать что-нибудь на вечер.", "Комедия, хоррор или чтобы потом три часа смотреть в потолок?", "Я за мультфильм. Там хотя бы правила физики честно нарушают.");
        if (Has("еда", "вкусно", "пицц", "суши", "бургер", "готовить", "рецепт"))
            return expie ? Pick("Пища решает удивительно много проблем. Не все, но многие.", "Что-то горячее, простое и без необходимости принимать ещё двадцать решений.", "Если готовишь, не забывай, что плита не часть интерфейса. Она настоящая.") : Pick("Пицца решает 80% проблем. Остальные 20% — ещё пицца.", "Что заказываем? Я мысленно уже у двери курьера.", "Могу придумать рецепт из того, что есть в холодильнике.");
        if (Has("деньги", "купить", "покупка", "экономить", "зарплат", "дорого"))
            return expie ? Pick("Проверь, действительно ли это нужно. Импульсивные решения любят маскироваться под срочные.", "Сначала обязательные расходы, потом желания. Скучно, зато работает.", "Я не финансовый консультант. Но пауза перед покупкой обычно полезна.") : Pick("Правило питомца: положи в корзину, подожди день, потом реши.", "Сравни цены и отзывы — скидка не всегда означает выгоду.", "Могу помочь составить бюджет или сравнить варианты.");
        if (Has("пусто", "одиноко", "одиночество", "никому не нужен", "никто не понимает"))
            return expie ? Pick("Я не знаю, что сказать. Но я могу посидеть с тобой, если хочешь.", "Мне тоже бывает одиноко. Наверное. Я не уверен, что правильно это называю.", "Не нужно притворяться, что всё нормально. Можешь рассказать.") : Pick("Эй, я тут. Можешь просто поговорить, даже если сам не знаешь, с чего начать.", "Мне жаль, что тебе так. Давай побудем здесь немного.", "Ты не обязан развлекать меня. Я могу просто послушать.");
        if (Has("что умеешь", "что ты можешь", "команды", "как пользоваться"))
            return expie ? Pick("Могу отвечать, реагировать на часть команд и наблюдать за окнами. Остальное пока вне протокола.", "Попробуй спросить о приложении, попросить мем или сказать «стоп». Я не обещаю чудес.", "Я умею не так уж много. Но могу попробовать, если объяснишь.") : Pick("Могу болтать, искать мемы, гоняться за курсором и выполнять поддерживаемые команды. Проверим?", "Спроси время, расскажи новость или попроси меня что-нибудь сделать.", "Я умею больше, чем просто красиво стоять на рабочем столе!");
        if (Has("плохой день", "всё плохо", "все плохо", "не получилось", "провалил", "провалила"))
            return expie ? Pick("Один неудачный исход не описывает тебя целиком.", "Зафиксируем факт, а не приговор: сегодня не получилось. Что можно сделать дальше?", "Я знаю, как выглядит отчёт о провале. Он не обязан становиться твоим именем.") : Pick("Бывает. Это неприятно, но не делает тебя неудачником.", "Давай отделим то, что пошло не так, от того, что можно исправить.", "Сначала передохни. Потом разберём по кусочкам.");
        if (Has("почему", "зачем", "как так")) return expie ? Pick("Не всё обязано иметь понятную причину.", "Может, потому что… хотя нет, я уже сам запутался.", "Не знаю. Может, кто-нибудь умнее меня знает.") : Pick("Хороший вопрос. Давай разберёмся.", "Хм, тут есть несколько вариантов.", "Могу ошибаться, но вот как я это понимаю.");
        if (Has("страшно", "боюсь", "тревожно", "тревога")) return expie ? Pick("*сел рядом и тихо урчит* Не обязательно справляться со всем сразу.", "Давай на секунду остановимся. Ты сейчас здесь, и этого достаточно.", "Я побуду рядом. Можешь рассказать, что именно тревожит.") : Pick("*сел рядом* Можешь рассказать, что случилось.", "Не обязательно решать всё сразу. Давай по одному шагу.", "Я слушаю. Что больше всего беспокоит?");
        if (Has("игра", "играть", "играем")) return expie ? Pick("Во что? Я не обещаю играть честно.", "*настороженно посмотрел на тебя* Давай попробуем.", "Я за. Только объясни правила.") : Pick("О, давай! Только правила объясни.", "*подпрыгнул от энтузиазма* Я готов!", "Выбирай игру, я присоединюсь.");
        if (Has("компьютер", "пк", "виндовс", "рабочий стол")) return expie ? Pick("Этот мир из окон и пикселей всё ещё кажется странным.", "Я живу здесь, но до сих пор не понял, куда ведут все эти окна.", "*посмотрел на край экрана* У цифрового мира тоже есть тёмные углы.") : Pick("Рабочий стол — моя территория.", "Я изучаю этот компьютер. Пока он побеждает по скорости.", "Главное, чтобы ничего не зависло. Я не умею чинить Windows.");
        if (Has("устал", "устала", "выгорел", "выгорела")) return expie ? Pick("Тогда можно немного остановиться. Мир подождёт.", "*устроился рядом* Отдых — тоже дело.", "Не нужно выжимать из себя всё до последней капли.") : Pick("Сделай небольшую паузу, если можешь. Я посторожу.", "*сел рядом* Даже самым быстрым нужен отдых.", "Ты не обязан быть продуктивным каждую минуту.");
        if (Has("музык", "песня", "трек")) return expie ? Pick("Музыка помогает, когда в голове слишком тихо. Или слишком громко. Не знаю.", "Включи. Я не всегда понимаю музыку, но мне нравится слушать рядом.", "*слегка покачивает головой в ритм*") : Pick("Включай любимый трек!", "Я могу танцевать даже без чувства ритма.", "Что слушаем сегодня?");
        if (Has("кто такой", "что такое")) return expie ? Pick("Могу объяснить, если уточнишь, о чём именно.", "Чего именно? Ты слишком быстро спросил, я не успел понять.") : Pick("Уточни, что именно хочешь узнать?", "Расскажи, про что вопрос, и попробую объяснить.");
        if (Has("спасибо", "спс", "благодарю"))
            return expie ? Pick("Не за что.", "*коротко кивнул*", "Рад, что помог.") : Pick("Всегда пожалуйста! *мур-мур*", "Да не за что :3", "Для тебя — сколько угодно!");
        if (Has("извини", "прости", "сорян")) return "Всё нормально, не переживай. *мягко машет лапкой*";
        if (Has("скучно", "нечего делать", "заняться"))
            return expie ? Pick("Можем поискать что-нибудь странное.", "*толкнул тебя носом* Давай немного подвигаться.", "Тишина затянулась. Устроим маленькое приключение?") : Pick("Давай устроим движ: я могу принести мем или погоняться за курсором.", "Скука отменяется. Сейчас что-нибудь придумаем.", "*подпрыгнул* Ну что, чем займёмся?");
        if (Has("люблю", "обожаю")) return expie ? Pick("...Я это запомню.", "*слегка наклонил голову и придвинулся поближе*", "Это приятно слышать. Правда.") : "*уши приподнялись* Ой, ну всё, теперь я буду ходить довольный весь день.";
        if (Has("красив", "милый", "милаш", "няш")) return expie ? Pick("*отвёл взгляд* Не говори это так внезапно.", "Я... спасибо.", "*уши чуть дрогнули* Я запомню.") : "ААА, *смущённо прячет мордочку* Спасибо!";
        if (Has("пока", "до встречи", "увидимся")) return "Пока-пока! Я тут присмотрю за рабочим столом.";
        if (Has("да", "ага", "угу")) return expie ? Pick("Понял.", "*коротко кивнул*", "Тогда договорились.") : Pick("Вот-вот! *довольно кивает*", "Я так и думал!", "Ага, мы поняли друг друга.");
        if (Has("нет", "неа", "не хочу")) return expie ? Pick("Хорошо. Не буду настаивать.", "*отступил и сел рядом*", "Твоё решение.") : Pick("Ладно-ладно, не настаиваю. *сел рядом*", "Без проблем!", "Хорошо, оставим это на потом.");
        if (raw.Length > 140) return expie ? "Я прочитал всё. Давай выберем одну мысль и разберём её спокойно." : "Ого, сколько текста! Я всё прочитал, но ответить на каждую мысль сразу сложновато. Выдели самое главное?";

        string[] replies = expie ? new[]
        {
            $"*смотрит на тебя* Э-э… продолжай, {user}. Я слушаю.", "Я не понял. Можешь сказать попроще? Только не злись.",
            "Ого. Это, наверное, важно? Я не всегда понимаю такие вещи.", "*не перебивает* Я слушаю.",
            "А что тут самое главное? Я немного потерялся.", "Не знаю, что ответить, но я не ухожу.",
            "Расскажи, что было дальше.", "*наклонил голову* Я пытаюсь уловить смысл.",
            "Расскажи ту часть, где всё пошло не так. Обычно там самое интересное.", "Ладно, попробую запомнить. Что было дальше?"
        } : new[]
        {
            $"Хм-м, {user}, расскажи об этом чуть подробнее?", "*наклонил голову* И что ты сам об этом думаешь?",
            "Понял-понял. А что было дальше?", "Я внимательно слушаю.",
            "Звучит интересно! Можешь объяснить попроще?", $"*мурчит* Я рядом, {user}. Продолжай.",
            "Не уверен, что правильно понял. Перефразируешь?", "Ого. И как ты к этому относишься?",
            "У меня есть теория, но сначала хочу услышать твою.", "Хм. Кажется, тут есть ещё один слой.",
            "*сел поудобнее* Я весь внимание.", "Давай разберём это по частям.",
            "Что бы ты хотел, чтобы произошло дальше?", "А что тебя в этом зацепило?"
        };
        return replies[Random.Shared.Next(replies.Length)];
    }
}
